@login_required
@require_POST
def disconnect_social_account(request):
    account_id = request.POST.get('account_id')
    account = get_object_or_404(SocialAccount, id=account_id, user=request.user)
    account.delete()
    return JsonResponse({'status': 'disconnected', 'provider': account.provider})
